`timescale 1ns/1ps module tb_up_counter(); reg clk; reg reset_n; reg enable; wire [7:0] count; integer checks = 0; integer failed = 0; up_counter dut (.clk(clk), .reset_n(reset_n), .enable(enable), .count(count)); always #5 clk = ~clk; task check_val; input [7:0] expected; input [127:0] name; begin checks = checks + 1; #1; if (count !== expected) begin $display(\"CHECK %s FAIL\", name); failed = failed + 1; end else begin $display(\"CHECK %s PASS\", name); end end endtask initial begin clk = 0; reset_n = 0; enable = 0; #12; reset_n = 1; check_val(8'd0, \"reset_check\"); enable = 1; #10; check_val(8'd1, \"nominal_increment\"); enable = 0; #10; check_val(8'd1, \"hold_check\"); enable = 1; repeat(254) @(posedge clk); #1; check_val(8'd255, \"boundary_max\"); @(posedge clk); #1; check_val(8'd0, \"wrap_check\"); $display(\"SUMMARY checks=%0d failed=%0d\", checks, failed); if (failed == 0) $display(\"PASS\"); else $display(\"FAIL\"); $finish; end endmodule